const __pageData = JSON.parse('{"title":"JUnit单元测试入门","description":"从\\"测试是什么\\"讲到第一个 JUnit 单元测试真正跑通——四个测试阶段、三种测试方法、main 方法测试与 JUnit 单元的对比、快速入门四步（引入 junit-jupiter 依赖、在 test/java 建测试类、加 @Test、运行），附本机实测的测试输出与\\"绿色不代表没问题\\"的实测证据","frontmatter":{"title":"JUnit单元测试入门","published":"2026-09-29T00:00:00.000Z","description":"从\\"测试是什么\\"讲到第一个 JUnit 单元测试真正跑通——四个测试阶段、三种测试方法、main 方法测试与 JUnit 单元的对比、快速入门四步（引入 junit-jupiter 依赖、在 test/java 建测试类、加 @Test、运行），附本机实测的测试输出与\\"绿色不代表没问题\\"的实测证据","tags":["JavaWeb","测试","Maven"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-27-junit-intro.webp","order":27,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/27-JUnit单元测试入门.md","filePath":"posts/学习文档/JavaWeb学习笔记/27-JUnit单元测试入门.md"}');
